local card={api_version=1,id="LOOT_519",name="Geosculptor Yip",text="At the end of your turn, summon a random minion with Cost equal to your Armor <i>(up to 10)</i>.",set="LOOTAPALOOZA",type="minion",class="warrior",rarity="legendary",cost=8,attack=4,health=8,triggers={{event="turn_ended",timing="after",active_zones={"board"},condition=function(ctx,self,e)return e.player==ctx:controller(self)end,effect=function(ctx,self)local cost=math.min(10,ctx:entity(ctx:player(ctx:controller(self)).hero).armor);local c={}for _,id in ipairs(ctx:collectible_cards())do local d=ctx:card_definition(id);if d.type=="minion"and d.cost==cost then c[#c+1]=id end end;if #c>0 then ctx:random_value(c,"summon_selected")end end}}}
function card.summon_selected(ctx,self,id)ctx:summon(ctx:controller(self),id)end
return card
